sys_script.script:
(function executeRule(current, previous) {


    var colaboradorSysId = current.getValue('colaborador');
    if (!colaboradorSysId) return;

    // 1. Buscar capacidade mensal do colaborador
    var grColab = new GlideRecord('x_1971880_sigact_0_colaborador');
    if (!grColab.get(colaboradorSysId)) return;

    var capacidade = parseFloat(grColab.getValue('capacidade_mensal')) || 0;
    if (capacidade === 0) return;

    // 2. Somar percentual de todas as alocações ATIVAS do colaborador
    var grAloc = new GlideRecord('x_1971880_sigact_0_alocacao');
    grAloc.addQuery('colaborador', colaboradorSysId);
    grAloc.addQuery('status', 'ativa');
    grAloc.query();

    var totalPercentual = 0;
    while (grAloc.next()) {
        totalPercentual += parseFloat(grAloc.getValue('percentual_alocacao')) || 0;
    }

    // 3. Calcular proporção em relação à capacidade
    var proporcao = totalPercentual / capacidade * 100;

    // 4. Determinar o valor de Carga
    var carga;
    if (proporcao <= 80) {
        carga = 'ok';
    } else if (proporcao < 100) {
        carga = 'ideal';
    } else if (proporcao === 100) {
        carga = 'limite';
    } else {
        carga = 'sobrecarga';
    }

    // 5. Atualizar campo Carga no Colaborador
    var nomeColaborador = grColab.getDisplayValue('nome');
    grColab.setValue('carga', carga);
    grColab.update();

    // 6. Notificação visual
    var percentFormatado = proporcao.toFixed(0) + '%';
    var cargaLabel = carga.charAt(0).toUpperCase() + carga.slice(1);
    var msg = 'Alocação registrada. Carga atual de ' + nomeColaborador + ': ' + cargaLabel + ' (' + percentFormatado + ')';

    if (carga === 'sobrecarga') {
        gs.addErrorMessage('⚠️ Atenção! Carga atual de ' + nomeColaborador + ': Sobrecarga (' + percentFormatado + ')');
    } else {
        gs.addInfoMessage(msg);
    }

})(current, previous);
